import { useResizeObserver } from '@rocket.chat/fuselage-hooks';
import { styled, View } from '@tamagui/web';
import type { ReactNode } from 'react';

import type { ElementProps } from '../../types/ElementProps';
import { Box } from '../Box';
import { Icon, type IconProps } from '../Icon';

export type CalloutProps = ElementProps<HTMLElement> & {
	type?: 'info' | 'success' | 'warning' | 'danger';
	title?: ReactNode;
	children?: ReactNode;
	icon?: IconProps['name'];
	actions?: ReactNode;
};

const WRAPPER_LIMIT_SIZE = 420;

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

// Declared where they render: zero-runtime only erases a `styled()` whose every use is in its own module
const CalloutFrame = styled(View, {
	render: 'section',
	display: 'flex',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	padding: '12px',
	color: 'var(--rcx-callout-text-color, var(--rcx-color-font-default, #2f343d))',
	borderWidth: '1px',
	borderStyle: 'solid',
	borderColor: 'var(--rcx-callout-default-color, var(--rcx-color-font-secondary-info, #6c737a))',
	borderRadius: 'var(--rcx-callout-border-radius, var(--rcx-border-radius-medium, 0.25rem))',
	backgroundColor: 'var(--rcx-callout-background-color, var(--rcx-color-surface-light, #ffffff))',
	variants: {
		type: {
			info: {
				borderColor: 'var(--rcx-callout-info-color, var(--rcx-color-status-font-on-info, #095ad2))',
			},
			success: {
				borderColor: 'var(--rcx-callout-success-color, var(--rcx-color-status-font-on-success, #148660))',
			},
			warning: {
				borderColor: 'var(--rcx-callout-warning-color, var(--rcx-color-status-font-on-warning, #895f00))',
			},
			danger: {
				borderColor: 'var(--rcx-callout-danger-color, var(--rcx-color-status-font-on-danger, #9b1325))',
			},
		},
	},
});

const CalloutWrapper = styled(View, {
	display: 'block',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	overflow: 'hidden',
	justifyContent: 'space-between',
	flexGrow: 1,
	flexBasis: 0,
	marginInlineStart: '12px',
	variants: {
		large: {
			true: {
				display: 'flex',
				alignItems: 'center',
			},
			false: {},
		},
	},
});

const CalloutBody = styled(View, {
	display: 'flex',
	flexDirection: 'column',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	overflow: 'hidden',
});

const CalloutTitle = styled(View, {
	display: 'block',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	whiteSpace: 'nowrap',
	overflow: 'hidden',
	textOverflow: 'ellipsis',
	fontSize: '0.875rem',
	fontWeight: 700,
	lineHeight: '1.25rem',
	letterSpacing: '0rem',
});

const CalloutContent = styled(View, {
	display: 'block',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	fontSize: '0.875rem',
	fontWeight: 400,
	lineHeight: '1.25rem',
	letterSpacing: '0rem',
	variants: {
		afterTitle: {
			true: {
				marginBlockStart: '4px',
			},
			false: {},
		},
	},
});

const CalloutActions = styled(View, {
	display: 'block',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	variants: {
		large: {
			true: {},
			false: {
				marginBlockStart: '12px',
			},
		},
	},
});

// end of generated

/**
 * The `Callout` is used to get the user's attention explaining something important in the content of the current page.
 */
const Callout = ({ type, title, children, icon, className, actions, ...props }: CalloutProps) => {
	const { ref, borderBoxSize } = useResizeObserver();
	const isLarge = Boolean(borderBoxSize.inlineSize && borderBoxSize.inlineSize >= WRAPPER_LIMIT_SIZE);

	const defaultIcon =
		(type === 'info' && 'info-circled') ||
		(type === 'success' && 'checkmark-circled') ||
		(type === 'warning' && 'warning') ||
		(type === 'danger' && 'ban') ||
		'info-circled';

	return (
		<CalloutFrame
			render={<Box ref={ref} is='section' {...props} />}
			type={type}
			className={['rcx-callout', type && `rcx-callout--${type}`, className].filter(Boolean).join(' ')}
		>
			<Icon className='rcx-callout__icon' name={icon || defaultIcon} size='x20' />
			<CalloutWrapper
				render={<Box />}
				large={isLarge}
				className={isLarge ? 'rcx-callout__wrapper--large rcx-callout__wrapper' : 'rcx-callout__wrapper'}
			>
				<CalloutBody render={<Box />} className='rcx-callout__wrapper-content'>
					{title && (
						<CalloutTitle render={<Box />} className='rcx-callout__title'>
							{title}
						</CalloutTitle>
					)}
					{children && (
						<CalloutContent render={<Box />} afterTitle={Boolean(title)} className='rcx-callout__content'>
							{children}
						</CalloutContent>
					)}
				</CalloutBody>
				{actions && (
					<CalloutActions render={<Box />} large={isLarge} className='rcx-callout__actions'>
						{actions}
					</CalloutActions>
				)}
			</CalloutWrapper>
		</CalloutFrame>
	);
};

export default Callout;
